4. **Default driver value** — set in two places in `/bench/repo/cmd/memos/main.go`:
   - `viper.SetDefault("driver", "sqlite")` (in `func init()`, ~line 122)
   - `rootCmd.PersistentFlags().String("driver", "sqlite", "database driver")` (~line 130)

   The flag is bound to viper via `viper.BindPFlag("driver", ...)`, and env var override would be `MEMOS_DRIVER` (prefix `memos`, `-`→`_` via `viper.SetEnvKeyReplacer`). With no CLI flag or env var set, `viper.GetString("driver")` resolves to `"sqlite"`, which is assigned to `instanceProfile.Driver` at `main.go` line ~40 (`Driver: viper.GetString("driver")`).

5. Since `profile.Driver == "sqlite"`, `db.NewDBDriver` takes the `case "sqlite":` branch and calls `sqlite.NewDB(profile)`, returning a `*sqlite.DB` that implements `store.Driver`. This is the value stored in `Store.driver`, so `s.driver.CreateMemo` at step 2 dispatches to the sqlite package's implementation.

6. **The actual INSERT — `/bench/repo/store/db/sqlite/memo.go:16`**:
```go
func (d *DB) CreateMemo(ctx context.Context, create *store.Memo) (*store.Memo, error) {
	fields := []string{"`uid`", "`creator_id`", "`content`", "`visibility`", "`payload`"}
	placeholder := []string{"?", "?", "?", "?", "?"}
	payload := "{}"
	if create.Payload != nil {
		payloadBytes, err := protojson.Marshal(create.Payload)
		if err != nil {
			return nil, err
		}
		payload = string(payloadBytes)
	}
	args := []any{create.UID, create.CreatorID, create.Content, create.Visibility, payload}

	if create.CreatedTs != 0 {
		fields = append(fields, "`created_ts`")
		placeholder = append(placeholder, "?")
		args = append(args, create.CreatedTs)
	}
	if create.UpdatedTs != 0 {
		fields = append(fields, "`updated_ts`")
		placeholder = append(placeholder, "?")
		args = append(args, create.UpdatedTs)
	}

	stmt := "INSERT INTO `memo` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ") RETURNING `id`, `created_ts`, `updated_ts`, `row_status`"
	if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(
		&create.ID, &create.CreatedTs, &create.UpdatedTs, &create.RowStatus,
	); err != nil {
		return nil, err
	}
	return create, nil
}
